/* Conservative exact rational proof for calculator expressions; bounded integer arithmetic. */
typedef struct{int64_t n,d;} Rational;
static Rational exactAns={0,1},exactResult;
static __int128 rgcd(__int128 a,__int128 b){if(a<0)a=-a;if(b<0)b=-b;while(b){__int128 t=a%b;a=b;b=t;}return a;}
static Rational rat(__int128 n,__int128 d){if(!d)return (Rational){0,0};if(d<0){n=-n;d=-d;}__int128 g=rgcd(n,d);n/=g;d/=g;if(n>1000000000000LL||n< -1000000000000LL||d>1000000000000LL)return (Rational){0,0};return (Rational){(int64_t)n,(int64_t)d};}
static Rational rop(Rational a,Rational b,char op){if(!a.d||!b.d)return (Rational){0,0};if(op=='+')return rat((__int128)a.n*b.d+(__int128)b.n*a.d,(__int128)a.d*b.d);if(op=='-')return rat((__int128)a.n*b.d-(__int128)b.n*a.d,(__int128)a.d*b.d);if(op=='*')return rat((__int128)a.n*b.n,(__int128)a.d*b.d);return rat((__int128)a.n*b.d,(__int128)a.d*b.n);}
typedef struct{const char*p;int depth,error;Rational previous;} RParser;
static void rspace(RParser*p){while(isspace((unsigned char)*p->p))p->p++;}
static Rational rsum(RParser*);
static Rational ratom(RParser*p){rspace(p);if(++p->depth>64){p->error=1;p->depth--;return (Rational){0,0};}Rational a={0,0};if(*p->p=='('){p->p++;a=rsum(p);rspace(p);if(*p->p==')')p->p++;else p->error=1;}
 else if(isdigit((unsigned char)*p->p)||*p->p=='.'){__int128 n=0,d=1;int digits=0,dot=0;while(isdigit((unsigned char)*p->p)||(!dot&&*p->p=='.')){if(*p->p=='.'){dot=1;p->p++;continue;}if(++digits<=12){n=n*10+*p->p-'0';if(dot)d*=10;}p->p++;}if(digits>12||!digits)p->error=1;if(*p->p=='e'||*p->p=='E'){p->p++;int sign=1,e=0;if(*p->p=='+'||*p->p=='-')sign=*p->p++=='-'?-1:1;if(!isdigit((unsigned char)*p->p))p->error=1;while(isdigit((unsigned char)*p->p)){if(e<100)e=e*10+*p->p-'0';p->p++;}if(e>12)p->error=1;else while(e--){if(sign>0)n*=10;else d*=10;}}a=rat(n,d);}
 else if(isalpha((unsigned char)*p->p)){char name[24];int k=0;while(isalpha((unsigned char)*p->p)){if(k<23)name[k++]=tolower((unsigned char)*p->p);p->p++;}name[k]=0;if(!strcmp(name,"ans"))a=p->previous;else{rspace(p);if(*p->p!='(')p->error=1;else{p->p++;a=rsum(p);rspace(p);if(*p->p==')')p->p++;else p->error=1;if(a.d){if(!strcmp(name,"abs")){if(a.n<0)a.n=-a.n;}else if(!strcmp(name,"sqrt")){if(a.n<0)a.d=0;else{int64_t n=llround(sqrt((double)a.n)),d=llround(sqrt((double)a.d));a=(n*n==a.n&&d*d==a.d)?rat(n,d):(Rational){0,0};}}else if(!strcmp(name,"floor")||!strcmp(name,"ceil")||!strcmp(name,"round")){int64_t n=a.n/a.d,r=a.n%a.d;if(!strcmp(name,"floor")&&r<0)n--;if(!strcmp(name,"ceil")&&r>0)n++;if(!strcmp(name,"round")&&llabs(r)*2>=a.d)n+=r<0?-1:1;a=rat(n,1);}else a.d=0;}}}}
 else {p->error=1;}p->depth--;rspace(p);while(*p->p=='!'){p->p++;if(!a.d||a.d!=1||a.n<0||a.n>14)a.d=0;else{int64_t n=a.n;a=rat(1,1);for(int i=2;i<=n;i++)a=rop(a,rat(i,1),'*');}rspace(p);}return a;}
static Rational runary(RParser*);
static Rational rpower(RParser*p){if(++p->depth>64){p->error=1;p->depth--;return (Rational){0,0};}Rational a=ratom(p);if(*p->p=='^'){p->p++;Rational b=runary(p);if(!b.d||b.d!=1||llabs(b.n)>40)a.d=0;else{Rational base=a;a=rat(1,1);for(int i=0;i<llabs(b.n);i++)a=rop(a,base,'*');if(b.n<0)a=rat(a.d,a.n);}}p->depth--;return a;}
static Rational runary(RParser*p){rspace(p);if(*p->p=='+'||*p->p=='-'){int neg=*p->p++=='-';if(++p->depth>64){p->error=1;p->depth--;return (Rational){0,0};}Rational a=runary(p);p->depth--;if(neg)a.n=-a.n;return a;}return rpower(p);}
static Rational rproduct(RParser*p){Rational a=runary(p);rspace(p);while(!p->error&&(*p->p=='*'||*p->p=='/'||*p->p=='('||isalpha((unsigned char)*p->p))){char op='*';if(*p->p=='*'||*p->p=='/')op=*p->p++;a=rop(a,runary(p),op);rspace(p);}return a;}
static Rational rsum(RParser*p){Rational a=rproduct(p);rspace(p);while(!p->error&&(*p->p=='+'||*p->p=='-')){char op=*p->p++;a=rop(a,rproduct(p),op);rspace(p);}return a;}
static Rational exactExpression(const char*s,Rational previous){RParser p={.p=s,.previous=previous};Rational a=rsum(&p);rspace(&p);if(p.error||*p.p)a.d=0;return a;}
static void exactNumberText(double value,Rational a,char*out,size_t size){if(fractionView&&a.d&&a.d<=1000000){if(a.d==1)snprintf(out,size,"%lld",(long long)a.n);else snprintf(out,size,"%lld/%lld",(long long)a.n,(long long)a.d);}else snprintf(out,size,"%.17g",value);}
